package com.fakelegacy.catalog;

import java.time.LocalDate;
import java.util.Optional;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PromotionRepository extends JpaRepository<Promotion, String> {

    @Query("select p from Promotion p where p.code = :code and p.validFrom <= :today and p.validTo >= :today "
            + "and p.usageCount < p.maxUsage")
    Optional<Promotion> findUsable(@Param("code") String code, @Param("today") LocalDate today);

    @Modifying
    @Query("update Promotion p set p.usageCount = p.usageCount + 1 where p.code = :code and p.usageCount < p.maxUsage")
    int consumeOne(@Param("code") String code);
}
